vips conv fixtures/colour.v fixtures/outputs/conv_colour_sharp_integer__vector.v fixtures/kernels/sharp.mat --precision integer
VIPS_NOVECTOR=1 vips conv fixtures/colour.v fixtures/outputs/conv_colour_sharp_integer.v fixtures/kernels/sharp.mat --precision integer
vips conv fixtures/colour.v fixtures/outputs/conv_colour_sharp_float__vector.v fixtures/kernels/sharp.mat --precision float
VIPS_NOVECTOR=1 vips conv fixtures/colour.v fixtures/outputs/conv_colour_sharp_float.v fixtures/kernels/sharp.mat --precision float
vips conv fixtures/colour.v fixtures/outputs/conv_colour_blur_integer__vector.v fixtures/kernels/blur.mat --precision integer
