# --- compass: impulse response (exact kernel-rotation reveal) ---
vips compass fixtures/impulse_mono.v fixtures/outputs/compass_impulse_sharp_t1_max_integer__vector.v fixtures/kernels/sharp.mat --times 1 --angle d45 --combine max --precision integer
VIPS_NOVECTOR=1 vips compass fixtures/impulse_mono.v fixtures/outputs/compass_impulse_sharp_t1_max_integer.v fixtures/kernels/sharp.mat --times 1 --angle d45 --combine max --precision integer
vips compass fixtures/impulse_mono.v fixtures/outputs/compass_impulse_sharp_t1_max_float__vector.v fixtures/kernels/sharp.mat --times 1 --angle d45 --combine max --precision float
