vips compass fixtures/impulse_mono.v fixtures/outputs/compass_impulse_sharp_t1_sum_integer__vector.v fixtures/kernels/sharp.mat --times 1 --angle d45 --combine sum --precision integer
VIPS_NOVECTOR=1 vips compass fixtures/impulse_mono.v fixtures/outputs/compass_impulse_sharp_t1_sum_integer.v fixtures/kernels/sharp.mat --times 1 --angle d45 --combine sum --precision integer
vips compass fixtures/impulse_mono.v fixtures/outputs/compass_impulse_sharp_t1_sum_float__vector.v fixtures/kernels/sharp.mat --times 1 --angle d45 --combine sum --precision float
VIPS_NOVECTOR=1 vips compass fixtures/impulse_mono.v fixtures/outputs/compass_impulse_sharp_t1_sum_float.v fixtures/kernels/sharp.mat --times 1 --angle d45 --combine sum --precision float
vips compass fixtures/impulse_mono.v fixtures/outputs/compass_impulse_sharp_t2_max_integer__vector.v fixtures/kernels/sharp.mat --times 2 --angle d45 --combine max --precision integer
VIPS_NOVECTOR=1 vips compass fixtures/impulse_mono.v fixtures/outputs/compass_impulse_sharp_t2_max_integer.v fixtures/kernels/sharp.mat --times 2 --angle d45 --combine max --precision integer
vips compass fixtures/impulse_mono.v fixtures/outputs/compass_impulse_sharp_t2_max_float__vector.v fixtures/kernels/sharp.mat --times 2 --angle d45 --combine max --precision float
VIPS_NOVECTOR=1 vips compass fixtures/impulse_mono.v fixtures/outputs/compass_impulse_sharp_t2_max_float.v fixtures/kernels/sharp.mat --times 2 --angle d45 --combine max --precision float
vips compass fixtures/impulse_mono.v fixtures/outputs/compass_impulse_sharp_t2_sum_integer__vector.v fixtures/kernels/sharp.mat --times 2 --angle d45 --combine sum --precision integer
VIPS_NOVECTOR=1 vips compass fixtures/impulse_mono.v fixtures/outputs/compass_impulse_sharp_t2_sum_integer.v fixtures/kernels/sharp.mat --times 2 --angle d45 --combine sum --precision integer
vips compass fixtures/impulse_mono.v fixtures/outputs/compass_impulse_sharp_t2_sum_float__vector.v fixtures/kernels/sharp.mat --times 2 --angle d45 --combine sum --precision float
VIPS_NOVECTOR=1 vips compass fixtures/impulse_mono.v fixtures/outputs/compass_impulse_sharp_t2_sum_float.v fixtures/kernels/sharp.mat --times 2 --angle d45 --combine sum --precision float
vips compass fixtures/impulse_mono.v fixtures/outputs/compass_impulse_sharp_t3_max_integer__vector.v fixtures/kernels/sharp.mat --times 3 --angle d45 --combine max --precision integer
VIPS_NOVECTOR=1 vips compass fixtures/impulse_mono.v fixtures/outputs/compass_impulse_sharp_t3_max_integer.v fixtures/kernels/sharp.mat --times 3 --angle d45 --combine max --precision integer
