VIPS_NOVECTOR=1 vips compass fixtures/impulse_mono.v fixtures/outputs/compass_impulse_sharp_t3_sum_float.v fixtures/kernels/sharp.mat --times 3 --angle d45 --combine sum --precision float

# --- compass: on ported test_compass inputs (sample.jpg mono/colour) ---
# NB: test_compass only asserts output dims == input dims (no numeric probe);
# we still capture avg + a probe point as a behavioral spot-check.
