# --- convsep: gaussmat(sigma=2, min_ampl=0.1) 2D vs separable ---
vips gaussmat fixtures/kernels/gaussmat_sample_2d_integer.mat 2.0 0.1 --precision integer
vips gaussmat fixtures/kernels/gaussmat_sample_sep_integer.mat 2.0 0.1 --precision integer --separable
vips conv fixtures/sample_mono.v fixtures/outputs/convsep_mono_conv2d_integer__vector.v fixtures/kernels/gaussmat_sample_2d_integer.mat --precision integer
VIPS_NOVECTOR=1 vips conv fixtures/sample_mono.v fixtures/outputs/convsep_mono_conv2d_integer.v fixtures/kernels/gaussmat_sample_2d_integer.mat --precision integer
vips convsep fixtures/sample_mono.v fixtures/outputs/convsep_mono_convsep1d_integer__vector.v fixtures/kernels/gaussmat_sample_sep_integer.mat --precision integer
